    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Reference Entry */
.reference-entry {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: white;
}

.reference-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.reference-entry__header h4 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.char-count {
    display: block;
    text-align: right;
    color: #6c757d;
    font-size: 0.875rem;
    margin-top: 0.25rem;
}

/* Review */
