+    color: #666;
+    margin-bottom: 0.25rem;
+}
+
+.step--current .step__number {
+    border-color: #0d6efd;
+    background: #0d6efd;
+    color: white;
+}
+
+.step--completed .step__number {
+    border-color: #198754;
+    background: #198754;
+    color: white;
+}
+
+.step--future {
+    opacity: 0.5;
+}
+
+.step__label {
+    font-size: 0.75rem;
+    text-align: center;
+    color: #333;
+}
+
+.step__connector {
+    width: 2rem;
+    height: 2px;
+    background: #ccc;
+    align-self: center;
+    margin-bottom: 1rem;
+}
+
+.step__connector--completed {
+    background: #198754;
+}
+
+/* Form */
+.form-step {
+    background: #f8f9fa;
+    border-radius: 8px;
+    padding: 2rem;
+    border: 1px solid #dee2e6;
+}
+
+.form-step h2 {
+    margin-top: 0;
+    margin-bottom: 1.5rem;
+    color: #212529;
+}
+
+.form-group {
+    margin-bottom: 1rem;
+}
+
+.form-group label {
+    display: block;
+    font-weight: 500;
+    margin-bottom: 0.25rem;
+    color: #495057;
+}
+
+.form-control {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #ced4da;
+    border-radius: 4px;
+    font-size: 1rem;
+    box-sizing: border-box;
+}
+
+.form-control:focus {
+    outline: none;
+    border-color: #0d6efd;
+    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.25);
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+.form-hint {
+    color: #6c757d;
+    margin-bottom: 1rem;
+}
+
+.form-actions {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    gap: 1rem;
+}
+
+/* Buttons */
+.btn {
+    padding: 0.5rem 1.5rem;
+    border-radius: 4px;
+    font-size: 1rem;
+    font-weight: 500;
+    cursor: pointer;
+    border: none;
+    transition: background 0.2s, opacity 0.2s;
+}
+
+.btn:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-primary {
+    background: #0d6efd;
+    color: white;
+    margin-left: auto;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-outline {
+    background: white;
+    color: #0d6efd;
+    border: 1px solid #0d6efd;
+}
+
+.btn-outline:hover:not(:disabled) {
+    background: #e7f1ff;
+}
+
+.btn-secondary {
+    background: #6c757d;
+    color: white;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover:not(:disabled) {
+    background: #5c636a;
+}
+
+.btn-danger {
+    background: #dc3545;
+    color: white;
+}
+
+.btn-sm {
+    padding: 0.25rem 0.75rem;
+    font-size: 0.875rem;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #0d6efd;
+    cursor: pointer;
+    font-size: 0.875rem;
+    text-decoration: underline;
+    padding: 0;
+}
+
+.btn-link:hover {
+    color: #0a58ca;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.1rem;
+}
+
+/* Validation */
+.validation-summary {
+    background: #f8d7da;
+    color: #842029;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-top: 1rem;
+}
+
+.field-error {
+    color: #dc3545;
+    font-size: 0.875rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+/* Work Entry */
+.work-entry {
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: white;
+}
+
+.work-entry__header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry__header h4 {
+    margin: 0;
+}
+
+.checkbox-label {
+    display: inline-flex !important;
+    align-items: center;
+    gap: 0.5rem;
+    font-weight: normal !important;
+    margin-top: 0.5rem;
+}
+
+.checkbox-label input[type="checkbox"] {
+    width: auto;
+}
+
+/* Reference Entry */
+.reference-entry {
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: white;
+}
+
+.reference-entry__header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.reference-entry__header h4 {
+    margin: 0;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 200px;
+    resize: vertical;
+}
+
+.char-count {
+    display: block;
+    text-align: right;
+    color: #6c757d;
+    font-size: 0.875rem;
+    margin-top: 0.25rem;
+}
+
+/* Review */
+.review-section {
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: white;
+}
+
+.review-section__header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section__header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+}
+
+.review-data {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-data dt {
+    font-weight: 500;
+    color: #495057;
+}
+
+.review-data dd {
+    margin: 0;
+}
+
+.review-work-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    font-size: 0.875rem;
+    color: #6c757d;
+}
+
+.review-description {
+    margin: 0.25rem 0 0;
+    font-size: 0.9rem;
+    color: #495057;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    margin: 0;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.submission-confirmation h3 {
+    color: #198754;
+    font-size: 1.5rem;
+}
+

